import{getSettings,getStats}from'../shared/storage.js';import{chooseMessage}from'../shared/messages.js';let audio;async function init(){const[s,st]=await Promise.all([getSettings(),getStats()]);document.querySelector('#message').textContent=chooseMessage(s.angerLevel);document.querySelector('#counter').textContent=st.sessionCount;const b=document.querySelector('#audio');if(!s.audioEnabled){b.hidden=true;return}audio=new Audio(`../audio/angry${1+Math.floor(Math.random()*3)}.mp3`);audio.volume=s.volume;try{await audio.play();b.hidden=true}catch{document.querySelector('#audio-note').textContent='Audio needs a tap because of browser autoplay rules.'}}document.querySelector('#back').addEventListener('click',()=>history.back());document.querySelector('#continue').addEventListener('click',()=>history.back());document.querySelector('#audio').addEventListener('click',async()=>{if(audio)try{await audio.play(),document.querySelector('#audio').hidden=true}catch{}});init();
